def get_orders_with_items(user_id):
    orders = db.query('SELECT * FROM orders WHERE user_id = ?', user_id)
    order_ids = [o['id'] for o in orders]
    items = db.query(f"SELECT * FROM order_items WHERE order_id IN ({','.join(['?']*len(order_ids))})", *order_ids)
    items_map = {}
    for item in items:
        items_map.setdefault(item['order_id'], []).append(item)
    result = []
    for order in orders:
        result.append({'order': order, 'items': items_map.get(order['id'], [])})
    return result
